package main

import "unicode"

// reservedWords are the ECMAScript reserved words. A key that happens to spell
// one of these can't be written with dot notation, so it always gets the
// bracket treatment even though it looks like a perfectly good identifier.
var reservedWords = map[string]bool{
	"break": true, "case": true, "catch": true, "class": true,
	"const": true, "continue": true, "debugger": true, "default": true,
	"delete": true, "do": true, "else": true, "export": true,
	"extends": true, "false": true, "finally": true, "for": true,
	"function": true, "if": true, "import": true, "in": true,
	"instanceof": true, "new": true, "null": true, "return": true,
	"super": true, "switch": true, "this": true, "throw": true,
	"true": true, "try": true, "typeof": true, "var": true,
	"void": true, "while": true, "with": true, "yield": true,
}

// idStartCategories mirrors the ECMAScript UnicodeIDStart set.
var idStartCategories = []*unicode.RangeTable{unicode.L, unicode.Nl}

// idPartCategories mirrors UnicodeIDContinue: the start set plus marks,
// decimal digits and connector punctuation.
var idPartCategories = []*unicode.RangeTable{
	unicode.L, unicode.Nl, unicode.Mn, unicode.Mc, unicode.Nd, unicode.Pc,
}

func isIdentStart(r rune) bool {
	if r == '$' || r == '_' {
		return true
	}
	return unicode.In(r, idStartCategories...)
}

func isIdentPart(r rune) bool {
	if r == '$' || r == '_' {
		return true
	}
	return unicode.In(r, idPartCategories...)
}

// validIdentifier reports whether s can be used with dot notation, i.e. it is a
// well formed identifier name and isn't one of the reserved words.
func validIdentifier(s string) bool {
	if s == "" {
		return false
	}
	if reservedWords[s] {
		return false
	}
	for i, r := range s {
		if r == unicode.ReplacementChar {
			// Came from a byte sequence that wasn't valid UTF-8; not
			// something we want to emit bare.
			if !hasLiteralReplacementCharAt(s, i) {
				return false
			}
		}
		if i == 0 {
			if !isIdentStart(r) {
				return false
			}
			continue
		}
		if !isIdentPart(r) {
			return false
		}
	}
	return true
}

// hasLiteralReplacementCharAt distinguishes a real U+FFFD in the string from a
// decoding error surfaced by range-over-string.
func hasLiteralReplacementCharAt(s string, i int) bool {
	return len(s) >= i+3 && s[i] == 0xEF && s[i+1] == 0xBF && s[i+2] == 0xBD
}

