package main

import "strings"

const hexUpper = "0123456789ABCDEF"

// quoteGron renders s as a JSON string literal using the escaping gron applies
// to the assignments it prints. It differs from encoding/json's escaping in
// three ways: the \u escapes use upper case hex digits, DEL and the C1 control
// block (U+007F-U+009F) are escaped too, and HTML-significant characters are
// left alone.
//
// U+2028 and U+2029 are escaped because gron output is meant to be valid
// JavaScript, and those two are line terminators there.
func quoteGron(s string) string {
	var b strings.Builder
	b.Grow(len(s) + 2)
	b.WriteByte('"')
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c == '"':
			b.WriteString(`\"`)
		case c == '\\':
			b.WriteString(`\\`)
		case c == '\b':
			b.WriteString(`\b`)
		case c == '\f':
			b.WriteString(`\f`)
		case c == '\n':
			b.WriteString(`\n`)
		case c == '\r':
			b.WriteString(`\r`)
		case c == '\t':
			b.WriteString(`\t`)
		case c < 0x20:
			writeShortUnicodeEscape(&b, rune(c))
		case c == 0x7F:
			writeShortUnicodeEscape(&b, rune(c))
		case c == 0xC2 && i+1 < len(s) && s[i+1] >= 0x80 && s[i+1] <= 0x9F:
			// The C1 controls U+0080-U+009F encode as 0xC2 0x80-0x9F.
			writeShortUnicodeEscape(&b, rune(s[i+1]))
			i++
		case c == 0xE2 && i+2 < len(s) && s[i+1] == 0x80 &&
			(s[i+2] == 0xA8 || s[i+2] == 0xA9):
			// U+2028 LINE SEPARATOR / U+2029 PARAGRAPH SEPARATOR.
			writeShortUnicodeEscape(&b, rune(0x2028+(s[i+2]-0xA8)))
			i += 2
		default:
			b.WriteByte(c)
		}
	}
	b.WriteByte('"')
	return b.String()
}

func writeShortUnicodeEscape(b *strings.Builder, r rune) {
	b.WriteString(`\u`)
	b.WriteByte(hexUpper[(r>>12)&0xF])
	b.WriteByte(hexUpper[(r>>8)&0xF])
	b.WriteByte(hexUpper[(r>>4)&0xF])
	b.WriteByte(hexUpper[r&0xF])
}

