package main

import (
	"strconv"
	"strings"
)

// tokenType tells the renderer how to colourise a piece of a statement, and
// tells the sorter and the ungronner what a piece means.
type tokenType int

const (
	typIgnored tokenType = iota // whitespace and other filler
	typBare                     // an identifier used with dot notation
	typNumericKey               // an array index
	typQuotedKey                // an object key that needed quoting
	typPunct                    // the dot between path elements
	typLBracket                 // [
	typRBracket                 // ]
	typEquals                   // the " = " in the middle
	typSemi                     // the trailing ;
	typString                   // a string value
	typNumber                   // a numeric value
	typTrue
	typFalse
	typNull
	typEmptyObject // the {} placeholder for an object
	typEmptyArray  // the [] placeholder for an array
)

// isValue reports whether a token can appear on the right hand side of an
// assignment.
func (t tokenType) isValue() bool {
	switch t {
	case typString, typNumber, typTrue, typFalse, typNull, typEmptyObject, typEmptyArray:
		return true
	}
	return false
}

// isKey reports whether a token names a step in the path.
func (t tokenType) isKey() bool {
	switch t {
	case typBare, typNumericKey, typQuotedKey:
		return true
	}
	return false
}

type token struct {
	text string
	typ  tokenType
}

// statement is a whole assignment, held as the exact sequence of tokens that
// spell it out. Keeping the raw text of every token means a statement can
// always be echoed back verbatim, which is what the ungron error messages do.
type statement []token

// String renders the statement without colour.
func (s statement) String() string {
	var b strings.Builder
	for _, t := range s {
		b.WriteString(t.text)
	}
	return b.String()
}

// colorString renders the statement with each token wrapped in its colour.
func (s statement) colorString(c *palette) string {
	var b strings.Builder
	for _, t := range s {
		c.write(&b, t.typ, t.text)
	}
	return b.String()
}

// withBare appends a dot and a bare identifier.
func (s statement) withBare(key string) statement {
	out := make(statement, 0, len(s)+2)
	out = append(out, s...)
	return append(out, token{".", typPunct}, token{key, typBare})
}

// withQuoted appends a bracketed, quoted object key.
func (s statement) withQuoted(key string) statement {
	out := make(statement, 0, len(s)+3)
	out = append(out, s...)
	return append(out,
		token{"[", typLBracket},
		token{quoteGron(key), typQuotedKey},
		token{"]", typRBracket})
}

// withIndex appends a bracketed array index.
func (s statement) withIndex(i int) statement {
	out := make(statement, 0, len(s)+3)
	out = append(out, s...)
	return append(out,
		token{"[", typLBracket},
		token{strconv.Itoa(i), typNumericKey},
		token{"]", typRBracket})
}

// withKey appends whichever form of object key suits the name.
func (s statement) withKey(key string) statement {
	if validIdentifier(key) {
		return s.withBare(key)
	}
	return s.withQuoted(key)
}

// assign completes the statement with " = ", the value and a semicolon.
func (s statement) assign(v token) statement {
	return append(s, token{" = ", typEquals}, v, token{";", typSemi})
}

// keys returns the tokens naming the path, dropping the punctuation and
// everything from the equals sign onwards. The leading root identifier is
// included.
func (s statement) keys() []token {
	var out []token
	for _, t := range s {
		if t.typ == typEquals {
			break
		}
		if t.typ.isKey() {
			out = append(out, t)
		}
	}
	return out
}

// value returns the token being assigned, if the statement has one.
func (s statement) value() (token, bool) {
	for i, t := range s {
		if t.typ == typEquals {
			for _, v := range s[i+1:] {
				if v.typ.isValue() {
					return v, true
				}
			}
			return token{}, false
		}
	}
	return token{}, false
}

// less orders statements the way gron prints them: token by token along the
// path, with array indices compared as numbers rather than as text so that
// [9] lands before [10]. Everything else compares bytewise, which is why an
// object key of "a10" still sorts before "a9".
func (s statement) less(o statement) bool {
	n := len(s)
	if len(o) < n {
		n = len(o)
	}
	for i := 0; i < n; i++ {
		a, b := s[i], o[i]
		if a.typ == typNumericKey && b.typ == typNumericKey {
			na, erra := strconv.Atoi(a.text)
