package main

import (
	"io"
	"os"
	"strings"
)

// ANSI SGR sequences. The "off" sequences reset each attribute that the "on"
// sequence set, so a bold blue is turned off with 0 (colour) and 22 (bold)
// rather than a blanket reset.
const (
	onBlueBold = "\x1b[34;1m"
	offBlueBold = "\x1b[0;22m"
	onBold      = "\x1b[1m"
	offBold     = "\x1b[22m"
	onRed       = "\x1b[31m"
	onGreen     = "\x1b[32m"
	onYellow    = "\x1b[33m"
	onCyan      = "\x1b[36m"
	onMagenta   = "\x1b[35m"
	offPlain    = "\x1b[0m"
)

// palette wraps the pieces of gron's output in colour. A nil-ish palette (one
// with enabled == false) writes everything through untouched, which keeps the
// rendering code free of conditionals.
type palette struct {
	enabled bool
}

func (p *palette) wrap(typ tokenType) (string, string) {
	if !p.enabled {
		return "", ""
	}
	switch typ {
	case typBare:
		return onBlueBold, offBlueBold
	case typQuotedKey, typString:
		return onYellow, offPlain
	case typNumericKey, typNumber:
		return onRed, offPlain
	case typTrue, typFalse, typNull:
		return onCyan, offPlain
	case typLBracket, typRBracket, typEmptyObject, typEmptyArray:
		return onMagenta, offPlain
	}
	return "", ""
}

func (p *palette) write(b *strings.Builder, typ tokenType, text string) {
	on, off := p.wrap(typ)
	b.WriteString(on)
	b.WriteString(text)
	b.WriteString(off)
}

func (p *palette) sprint(typ tokenType, text string) string {
	on, off := p.wrap(typ)
	if on == "" && off == "" {
		return text
	}
	return on + text + off
}

// wantColor decides whether to emit escape sequences.
//
// The baseline is "colour if we're talking to a terminal that can show it".
// --monochrome turns that off and --colorize turns it on, with --colorize
// winning if both are given. A non-empty NO_COLOR in the environment overrules
// everything, including an explicit --colorize.
func wantColor(w io.Writer, colorize, monochrome bool) bool {
	noColor := os.Getenv("NO_COLOR") != ""

	on := !noColor && os.Getenv("TERM") != "dumb" && isTerminal(w)
	if monochrome {
		on = false
	}
	if colorize {
		on = true
	}
	if noColor {
		on = false
	}
	return on
}

func isTerminal(w io.Writer) bool {
	f, ok := w.(*os.File)
	if !ok {
		return false
	}
	return fdIsTerminal(f.Fd())
}

