package main

import (
	"syscall"
	"unsafe"
)

// fdIsTerminal asks the kernel for the terminal settings of fd. Only a real
// terminal answers, which is exactly the test we want: a pipe or a regular
// file must not get escape sequences.
func fdIsTerminal(fd uintptr) bool {
	var termios syscall.Termios
	_, _, errno := syscall.Syscall6(syscall.SYS_IOCTL, fd, syscall.TCGETS,
		uintptr(unsafe.Pointer(&termios)), 0, 0, 0)
	return errno == 0
}

