package main

import (
	"encoding/json"
	"sort"
	"strings"
)

// gronRoot is the identifier every generated path hangs off.
const gronRoot = "json"

// makeStatements walks a decoded JSON document and produces one assignment per
// node. Containers get an assignment of their own holding an empty literal, so
// that an empty object or array still shows up in the output and so that
// ungronning can tell an object from an array.
func makeStatements(prefix statement, v interface{}) []statement {
	switch t := v.(type) {
	case map[string]interface{}:
		out := []statement{prefix.assign(token{"{}", typEmptyObject})}
		for k, sub := range t {
			out = append(out, makeStatements(prefix.withKey(k), sub)...)
		}
		return out

	case []interface{}:
		out := []statement{prefix.assign(token{"[]", typEmptyArray})}
		for i, sub := range t {
			out = append(out, makeStatements(prefix.withIndex(i), sub)...)
		}
		return out

	default:
		return []statement{prefix.assign(valueToken(v))}
	}
}

// valueToken renders a leaf value. Numbers keep the exact text they had in the
// input: reformatting them would lose precision on big integers and would
// quietly rewrite things like 1.0 or 3.0e2.
func valueToken(v interface{}) token {
	switch t := v.(type) {
	case string:
		return token{quoteGron(t), typString}
	case json.Number:
		return token{t.String(), typNumber}
	case bool:
		if t {
			return token{"true", typTrue}
		}
		return token{"false", typFalse}
	case nil:
		return token{"null", typNull}
	case map[string]interface{}:
		return token{"{}", typEmptyObject}
	case []interface{}:
		return token{"[]", typEmptyArray}
	}
	return token{"null", typNull}
}

// rootStatement is the starting path, `json`.
func rootStatement() statement {
	return statement{{gronRoot, typBare}}
}

func sortStatements(ss []statement) {
	sort.Slice(ss, func(i, j int) bool { return ss[i].less(ss[j]) })
}

// renderGron writes statements in the `json.a.b = 1;` form.
func renderGron(ss []statement, p *palette) string {
	var b strings.Builder
	for _, s := range ss {
		if p.enabled {
			b.WriteString(s.colorString(p))
		} else {
			b.WriteString(s.String())
		}
		b.WriteByte('\n')
	}
	return b.String()
}

// renderJSONStream writes statements as one `[[path],value]` array per line.
func renderJSONStream(ss []statement, p *palette) string {
	var b strings.Builder
	for _, s := range ss {
		b.WriteString(p.sprint(typLBracket, "["))
		b.WriteString(p.sprint(typLBracket, "["))

		keys := s.keys()
		// keys[0] is the root identifier, which isn't part of the path.
		for i, k := range keys[1:] {
			if i > 0 {
				b.WriteByte(',')
			}
			switch k.typ {
			case typNumericKey:
				b.WriteString(p.sprint(typNumericKey, k.text))
			case typQuotedKey:
				b.WriteString(p.sprint(typQuotedKey, k.text))
			default:
				b.WriteString(p.sprint(typQuotedKey, quoteGron(k.text)))
			}
		}

		b.WriteString(p.sprint(typRBracket, "]"))
		b.WriteByte(',')
		if v, ok := s.value(); ok {
			b.WriteString(p.sprint(v.typ, v.text))
		}
		b.WriteString(p.sprint(typRBracket, "]"))
		b.WriteByte('\n')
	}
	return b.String()
}

